import { stageColor, pipelineSourceOf, isColdLike, isPipelineSource, pipelineLabel, isCustomSource, type PipelineSource, historyLabel, lostStage, PIPELINE_SOURCE_LABEL, PIPELINE_STAGES, stageLabel, wonStage, workingStage, type PipelineStage, type StageDef } from "../../../shared/sales-pipeline";
import { Zap, Layers, Building2, ArrowRight, ChevronDown, ChevronUp, BarChart3, Bell, Cable, CalendarDays, CheckCircle2, CheckSquare, ChevronRight, ChevronsLeft, ChevronsRight, Copy, Download, Euro, Facebook, GripVertical, History, Kanban, ListChecks, Mail, Maximize2, Minimize2, Megaphone, MessageSquare, Phone, Plus, RefreshCw, Search, Settings2, Shuffle, StickyNote, Trash2, Unplug, Upload, UserPlus, Users, X } from "lucide-react";
